package icons

import (
	"bytes"
	"image"
	"image/color"
	"image/png"
	"math"

	"github.com/egoist/mygo/ui"
)

// IconPair pairs Solar Icons' official Line Duotone (Idle) and Bold Duotone (Active)
// variants so Koma switches seamlessly from airy etched crystal strokes at rest
// to rich solid dual-tone glyphs when active, pressed, or inside prominent CTAs.
//
// Icons sourced from Solar Icons (CC BY 4.0) via Iconify.
type IconPair struct {
	Idle   *ui.SVG
	Active *ui.SVG
}

// For returns the Bold Duotone glyph when active, or Line Duotone at rest.
func (p IconPair) For(active bool) *ui.SVG {
	if active && p.Active != nil {
		return p.Active
	}
	return p.Idle
}

func solarSVG(body string) *ui.SVG {
	return ui.MustParseSVG([]byte(
		`<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24">` + body + `</svg>`,
	))
}

func pair(idleBody, activeBody string) IconPair {
	return IconPair{
		Idle:   solarSVG(idleBody),
		Active: solarSVG(activeBody),
	}
}

