// AppIconPNG generates Koma's Liquid Glass + Solar squircle app icon PNG (size×size)
// with 2×2 supersampling, true superellipse curvature, 3D glass meniscus bevel,
// warm bottom caustic, and Solar-style curved viewfinder + frosted glass lens.
func AppIconPNG(size int) []byte {
	if size <= 0 {
		size = 128
	}
	img := image.NewNRGBA(image.Rect(0, 0, size, size))
	fs := float64(size)
	invSize := 1.0 / fs

	// 2×2 supersampling offsets for silky-smooth curves at both 32px tray and 512px desktop sizes.
	sub := [4][2]float64{
		{0.25, 0.25},
		{0.75, 0.25},
		{0.25, 0.75},
		{0.75, 0.75},
	}

	for y := 0; y < size; y++ {
		for x := 0; x < size; x++ {
			var accR, accG, accB, accA float64
			for _, o := range sub {
				// Normalized coordinates u, v in [-1, 1]
				u := ((float64(x)+o[0])*invSize - 0.5) * 2.0
				v := ((float64(y)+o[1])*invSize - 0.5) * 2.0
				r, g, b, a := evalKomaIconSample(u, v, fs)
				accR += r * a
				accG += g * a
				accB += b * a
				accA += a
			}
			a := accA * 0.25
			if a <= 0.0005 {
				continue
			}
			// Convert premultiplied average back to straight NRGBA so png.Encode never overflows
			r := clamp01(accR / accA)
			g := clamp01(accG / accA)
			b := clamp01(accB / accA)
			img.SetNRGBA(x, y, color.NRGBA{
				R: uint8(math.Round(r * 255)),
				G: uint8(math.Round(g * 255)),
				B: uint8(math.Round(b * 255)),
				A: uint8(math.Round(clamp01(a) * 255)),
			})
		}
	}

	var buf bytes.Buffer
	_ = png.Encode(&buf, img)
	return buf.Bytes()
}

// squircleSDF evaluates a smooth macOS-style superellipse SDF (radius ~0.94 in [-1,1]).
func squircleSDF(u, v, radius, power float64) float64 {
	ax := math.Abs(u) / radius
	ay := math.Abs(v) / radius
	m := math.Pow(math.Pow(ax, power)+math.Pow(ay, power), 1.0/power)
	return (m - 1.0) * radius
}

// roundedRectSDF evaluates a signed distance to a rounded square centered at origin.
func roundedRectSDF(u, v, half, r float64) float64 {
	qx := math.Abs(u) - (half - r)
	qy := math.Abs(v) - (half - r)
	return math.Hypot(math.Max(qx, 0), math.Max(qy, 0)) + math.Min(math.Max(qx, qy), 0) - r
}

func smoothstep(e0, e1, x float64) float64 {
	t := clamp01((x - e0) / (e1 - e0))
	return t * t * (3 - 2*t)
}

func evalKomaIconSample(u, v, sizePx float64) (r, g, b, a float64) {
	aa := 2.4 / math.Max(sizePx, 16)

	// 1. Continuous Apple superellipse body (n = 4.6)
	const bodyR = 0.94
	const bodyN = 4.6
	sd := squircleSDF(u, v, bodyR, bodyN)
	bodyMask := 1.0 - smoothstep(-aa, aa, sd)
	if bodyMask <= 0.0005 {
		return 0, 0, 0, 0
	}

	// Outward normal of the squircle via analytical superellipse gradient
	gx := math.Copysign(math.Pow(math.Abs(u)/bodyR+1e-6, bodyN-1), u)
	gy := math.Copysign(math.Pow(math.Abs(v)/bodyR+1e-6, bodyN-1), v)
	glen := math.Hypot(gx, gy)
	nx, ny := gx/glen, gy/glen

	// 2. Luminous Apple Tahoe sapphire -> cobalt -> deep indigo base mesh
	diag := clamp01(0.5 + 0.38*v + 0.22*u)
	r = lerp(0.18, 0.04, diag)
	g = lerp(0.73, 0.34, diag)
	b = lerp(1.00, 0.92, diag)

	// Upper-left cyan atmospheric bloom
	dCyan := math.Hypot(u+0.48, v+0.55)
	cyanBloom := math.Exp(-dCyan * dCyan * 1.9)
	r = lerp(r, 0.42, cyanBloom*0.48)
	g = lerp(g, 0.90, cyanBloom*0.52)
	b = lerp(b, 1.00, cyanBloom*0.35)

	// Lower-right deep indigo-violet depth glow
	dIndigo := math.Hypot(u-0.55, v-0.58)
	indigoBloom := math.Exp(-dIndigo * dIndigo * 1.8)
	r = lerp(r, 0.28, indigoBloom*0.46)
	g = lerp(g, 0.22, indigoBloom*0.48)
	b = lerp(b, 0.88, indigoBloom*0.35)

	// 3. Liquid Glass 3D curved dome optics (bevel shading + grazing rim glints + warm caustic)
	bevelW := 0.26
	tBevel := math.Pow(clamp01(-sd/bevelW), 1.0/1.4)
	domeH := math.Sqrt(math.Max(0, 1.0-(1.0-tBevel)*(1.0-tBevel)))
	depth := 1.0 - domeH

	// Subtle curved meniscus darkening inside rim
	innerBand := smoothstep(-0.14, -0.015, sd)
	r *= 1.0 - innerBand*0.16
	g *= 1.0 - innerBand*0.14
	b *= 1.0 - innerBand*0.08

	// Soft atmospheric top glass reflection
	topRefl := (1.0 - smoothstep(-0.75, 0.15, v)) * (1.0 - smoothstep(0.0, 0.95, math.Abs(u))) * 0.24
	r = lerp(r, 1.0, topRefl)
	g = lerp(g, 1.0, topRefl)
	b = lerp(b, 1.0, topRefl)

	// Razor-sharp curved specular rim glints (top-left, right & bottom bounce — bilalgursen style)
	rimW := math.Max(0.026, aa*2.1)
	rimLine := 1.0 - smoothstep(0.0, rimW*1.45, math.Abs(sd+rimW*1.15))
	up := math.Max(0, -ny)
	down := math.Max(0, ny)
	left := math.Max(0, -nx)
	right := math.Max(0, nx)
	rimDir := up*up*0.62 + left*left*0.48 + right*right*0.38 + down*down*0.18
	rimAmt := rimLine * rimDir * 0.72
	r = clamp01(r + rimAmt)
	g = clamp01(g + rimAmt)
	b = clamp01(b + rimAmt)

	// Warm internal caustic gathering along the bottom meniscus
	caustic := smoothstep(0.55, 0.98, depth) * down * 0.16
	r = clamp01(r + 1.00*caustic)
	g = clamp01(g + 0.92*caustic)
	b = clamp01(b + 0.86*caustic)

	// 4. Solar Duotone Floating Liquid Glass Viewfinder Symbol
	// 4a. Subtle ambient shadow beneath the floating viewfinder glyph
	shV := v - 0.045
	shRingSD := math.Abs(math.Hypot(u, shV)-0.56) - 0.045
	shSqSD := math.Abs(roundedRectSDF(u, shV, 0.50, 0.19)) - 0.055
	shCornerGate := smoothstep(0.11, 0.21, math.Max(math.Abs(u), math.Abs(shV))) *
		smoothstep(0.11, 0.21, math.Min(math.Abs(u), math.Abs(shV)))
	shDotSD := math.Hypot(u, shV) - 0.20
	shAlpha := math.Max(
		(1.0-smoothstep(-0.04, 0.08, shSqSD))*shCornerGate*0.24,
		(1.0-smoothstep(-0.04, 0.08, shDotSD))*0.24,
	)
	shAlpha = math.Max(shAlpha, (1.0-smoothstep(-0.04, 0.08, shRingSD))*0.10)
	r *= 1.0 - shAlpha
	g *= 1.0 - shAlpha
	b *= 1.0 - shAlpha

	// 4b. Soft translucent outer Solar duotone halo circle (opacity ~0.26)
	distC := math.Hypot(u, v)
	haloRingSD := math.Abs(distC-0.59) - 0.036
	haloMask := (1.0 - smoothstep(-aa, aa, haloRingSD)) * 0.28
	r = lerp(r, 1.0, haloMask)
	g = lerp(g, 1.0, haloMask)
	b = lerp(b, 1.0, haloMask)

	// 4c. Solar-style smooth curved squircle viewfinder brackets (4 continuous rounded corners)
	// Evaluate distance to a rounded square, masked strictly to the 4 corner arcs with round endcaps!
	const halfB = 0.46
	const radB = 0.18
	const thickB = 0.058
	bracketLineSD := math.Abs(roundedRectSDF(u, v, halfB, radB)) - thickB

	// Cut out the middle cross gaps cleanly, capping the 8 arm endpoints with circles!
	const gap = 0.155
	inArm := math.Abs(u) >= gap && math.Abs(v) >= gap
	var bracketSD float64
	if inArm {
		bracketSD = bracketLineSD
	} else {
		// Round endcaps at (±gap, ±halfB) and (±halfB, ±gap)
		d1 := math.Hypot(math.Abs(u)-gap, math.Abs(v)-halfB) - thickB
		d2 := math.Hypot(math.Abs(u)-halfB, math.Abs(v)-gap) - thickB
		bracketSD = math.Min(d1, d2)
	}
	bracketMask := 1.0 - smoothstep(-aa, aa, bracketSD)

	// Subtle cool-white gradient on the curved brackets so they read like illuminated glass
	brShade := lerp(1.0, 0.92, clamp01(0.5+0.5*v))
	r = lerp(r, brShade, bracketMask*0.97)
	g = lerp(g, lerp(1.0, 0.96, clamp01(0.5+0.5*v)), bracketMask*0.97)
	b = lerp(b, 1.0, bracketMask*0.97)

	// 4d. Center Solar Duotone Liquid Glass Lens (translucent frosted disc + bright crisp shutter core)
	lensOuterMask := 1.0 - smoothstep(-aa, aa, distC-0.245)
	if lensOuterMask > 0.001 {
		// Frosted crystal disc with top specular crescent
		lensFill := 0.30 + 0.16*clamp01(-v/0.245)
		r = lerp(r, 1.0, lensOuterMask*lensFill)
		g = lerp(g, 1.0, lensOuterMask*lensFill)
		b = lerp(b, 1.0, lensOuterMask*lensFill)

		// Delicate bright ring around the frosted lens
		lensRim := 1.0 - smoothstep(-aa, aa, math.Abs(distC-0.232)-0.016)
		r = lerp(r, 1.0, lensRim*0.58)
		g = lerp(g, 1.0, lensRim*0.58)
		b = lerp(b, 1.0, lensRim*0.58)
	}

	// Crisp pure-white center shutter pupil
	coreMask := 1.0 - smoothstep(-aa, aa, distC-0.115)
	r = lerp(r, 1.0, coreMask*0.98)
	g = lerp(g, 1.0, coreMask*0.98)
	b = lerp(b, 1.0, coreMask*0.98)

	return clamp01(r), clamp01(g), clamp01(b), bodyMask
}

func clamp01(v float64) float64 {
	if v < 0 {
		return 0
	}
	if v > 1 {
		return 1
	}
	return v
}

func lerp(a, b, t float64) float64 {
	return a + (b-a)*t
}
